[Fact]
public void Registry_mutation_preserves_malformed_existing_registry()
{
    var game=Path.Combine(root,"malformed-registry-game");Directory.CreateDirectory(game);
    var exe=Path.Combine(game,"Game.exe");File.WriteAllBytes(exe,[0x4d,0x5a]);
    var state=Path.Combine(root,"malformed-registry-state");Directory.CreateDirectory(state);
    var registry=new GameProfileRegistry(state);
    const string malformed="{ this is not valid json";
    File.WriteAllText(registry.RegistryPath,malformed);

    Assert.Throws<InvalidDataException>(()=>registry.AddGenericFromExecutable(exe));
    Assert.Equal(malformed,File.ReadAllText(registry.RegistryPath));
}

[Fact]
public void Registry_mutation_preserves_existing_invalid_profile_entries()
{
    var game=Path.Combine(root,"invalid-registry-game");Directory.CreateDirectory(game);
    var exe=Path.Combine(game,"Game.exe");File.WriteAllBytes(exe,[0x4d,0x5a]);
    var invalid=GameProfile.Generic("safe-game","Safe Game",game,"Game.exe","") with { Id=@"..\escaped" };
    var state=Path.Combine(root,"invalid-registry-state");Directory.CreateDirectory(state);
    var registry=new GameProfileRegistry(state);
    var json=JsonSerializer.Serialize(new[]{invalid},JsonOptions);
    File.WriteAllText(registry.RegistryPath,json);

    var replacement=GameProfile.Generic("replacement","Replacement",game,"Game.exe","");
    Assert.Throws<InvalidDataException>(()=>registry.Upsert(replacement));
    Assert.Equal(json,File.ReadAllText(registry.RegistryPath));
}

